func (q *Queries) SetLowBalanceState(ctx context.Context, arg SetLowBalanceStateParams) error {
	_, err := q.db.Exec(ctx, setLowBalanceState, arg.AccountID, arg.Below, arg.Episode)
	return err
}

const updateSubscription = `-- name: UpdateSubscription :one
UPDATE subscriptions
SET state = $1,
    name = $2,
    name_edited = $3,
    cadence = $4,
    amount_minor = $5,
    amount_edited = $6,
    currency = $7,
    category_id = $8,
    category_edited = $9,
    account_id = $10,
    confidence = $11,
    last_date = $12,
    next_date = $13,
    updated_at = now()
WHERE id = $14
RETURNING id, merchant_key, match_cadence, state, source, name, name_edited, cadence, amount_minor, amount_edited, currency, category_id, category_edited, account_id, confidence, last_date, next_date, created_at, updated_at
`

type UpdateSubscriptionParams struct {
	State          string
	Name           string
	NameEdited     bool
	Cadence        string
	AmountMinor    int64
	AmountEdited   bool
	Currency       string
	CategoryID     pgtype.UUID
	CategoryEdited bool
	AccountID      pgtype.UUID
	Confidence     string
	LastDate       pgtype.Date
	NextDate       pgtype.Date
	ID             pgtype.UUID
}

func (q *Queries) UpdateSubscription(ctx context.Context, arg UpdateSubscriptionParams) (Subscription, error) {
	row := q.db.QueryRow(ctx, updateSubscription,
		arg.State,
		arg.Name,
		arg.NameEdited,
		arg.Cadence,
		arg.AmountMinor,
		arg.AmountEdited,
		arg.Currency,
		arg.CategoryID,
		arg.CategoryEdited,
		arg.AccountID,
		arg.Confidence,
		arg.LastDate,
		arg.NextDate,
		arg.ID,
	)
	var i Subscription
	err := row.Scan(
		&i.ID,
		&i.MerchantKey,
		&i.MatchCadence,
		&i.State,
		&i.Source,
		&i.Name,
		&i.NameEdited,
		&i.Cadence,
		&i.AmountMinor,
		&i.AmountEdited,
		&i.Currency,
		&i.CategoryID,
		&i.CategoryEdited,
		&i.AccountID,
		&i.Confidence,
		&i.LastDate,
		&i.NextDate,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
